import { patchHtml } from '../phone-v2/dom-patch.mjs';
import { installSerialMotion,waitMotion } from '../ui/serial-motion.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=value=>structuredClone(value);
const uuid=()=>globalThis.crypto?.randomUUID?.()??('msg-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const safeContact=contact=>({id:String(contact.id),name:String(contact.name??contact.id),head:String(contact.head??''),subtitle:String(contact.subtitle??''),services:contact.services===true});
export function parsePhoneMessages(text){
 const source=String(text??'');if(source.length>2_000_000)return[];const result=[];
 for(const match of source.matchAll(/<phone_messages>\s*([\s\S]*?)\s*<\/phone_messages>/gi)){
  if(match[1].length>140000)continue;
  try{const list=JSON.parse(match[1]);if(!Array.isArray(list))continue;for(const x of list){if(!x||typeof x.contactId!=='string'||typeof x.text!=='string'||!x.text.trim()||!x.contactId.trim())continue;result.push({contactId:x.contactId.trim().slice(0,160),name:String(x.name??'').slice(0,100),text:x.text.slice(0,4000)});if(result.length===30)return result;}}catch{}
 }
 return result;
}
const messageHash=value=>{let hash=2166136261;for(const c of String(value)){hash^=c.codePointAt(0);hash=Math.imul(hash,16777619);}return (hash>>>0).toString(36);};
const sourceFloor=(message,floorId)=>message.from==='npc'&&(message.sourceFloorId===floorId||message.id.startsWith('reply:'+floorId+':'));

export class ContactChatStore{
 constructor({read=async()=>null,write=async()=>{},stage,contacts=[],getContacts=null,isWritable=()=>true,services=null}){this.read=read;this.write=write;this.stage=stage;this.contactSource=getContacts??(()=>contacts);this.isWritable=isWritable;this.services=services;this.state={schema:1,threads:{},seen:[]};this.listeners=new Set();this.queue=Promise.resolve();}
 get contacts(){return (this.contactSource()??[]).filter(x=>x&&typeof x.id==='string'&&x.known!==false).map(safeContact);}
 async init(){const state=await this.read();if(state&&state.threads&&typeof state.threads==='object'&&!Array.isArray(state.threads))this.state={schema:Number(state.schema)===2?2:1,threads:Object.fromEntries(Object.entries(state.threads).filter(([,messages])=>Array.isArray(messages)).map(([id,messages])=>[id,messages.filter(x=>x&&typeof x.id==='string'&&typeof x.text==='string'&&['npc','user'].includes(x.from)).map(x=>({...x,text:x.text.slice(0,4000)}))])),seen:Array.isArray(state.seen)?state.seen.filter(x=>typeof x==='string'):[]};return this;}
 get(id){return clone(Object.hasOwn(this.state.threads,id)?this.state.threads[id]:[]);}
 async save(){await this.write(clone(this.state));for(const fn of this.listeners)fn();}
 subscribe(fn){this.listeners.add(fn);return()=>this.listeners.delete(fn);}
 serial(fn){const job=this.queue.then(fn);this.queue=job.catch(()=>{});return job;}
 async receive(contactId,text,{id=uuid(),name=''}={}){return this.serial(async()=>{const contact=this.contacts.find(x=>x.id===contactId);if(!contact||typeof text!=='string'||!text.trim()||this.state.seen.includes(id))return false;const before=clone(this.state);this.state.seen.push(id);if(!Object.hasOwn(this.state.threads,contactId))Object.defineProperty(this.state.threads,contactId,{value:[],writable:true,enumerable:true,configurable:true});this.state.threads[contactId].push({id,from:'npc',name:contact.name,text:text.slice(0,4000),time:Date.now(),status:'received'});try{await this.save();}catch(error){this.state=before;throw error;}return true;});}
 async send(contactId,text){return this.serial(async()=>{if(!this.isWritable())throw Error('历史记录只能查看');const contact=this.contacts.find(x=>x.id===contactId);if(!contact)throw Error('联系人尚未建立联系');text=String(text).trim().slice(0,2000);if(!text)throw Error('请填写消息');if(typeof this.stage!=='function')throw Error('日程尚未连接');const id=uuid(),result=await this.stage({id,type:'character-chat',title:'消息 · '+contact.name,payload:{contactId,name:contact.name,text},hiddenPrompt:'这是通过手机发送给指定联系人的消息。按日程实际送出时处理；只让这位联系人在<phone_messages>里回复，不自动把联系人带到user所在地点。'});if(result?.ok===false)throw Error(result.message||'无法加入日程');if(!Object.hasOwn(this.state.threads,contactId))Object.defineProperty(this.state.threads,contactId,{value:[],writable:true,enumerable:true,configurable:true});this.state.threads[contactId].push({id,from:'user',text,time:Date.now(),status:'scheduled'});await this.save();return id;});}
 async markDispatched(actions){return this.serial(async()=>{const ids=new Set(actions.filter(x=>x.type==='character-chat').map(x=>x.id));let changed=false;for(const thread of Object.values(this.state.threads))for(const message of thread)if(ids.has(message.id)&&message.from==='user'&&message.status==='scheduled'){message.status='sent';changed=true;}if(changed)await this.save();});}
 async ingest(floorId,messages){return this.serial(async()=>{
  if(!Array.isArray(messages))return;floorId=String(floorId);const before=clone(this.state),known=new Map(this.contacts.map(x=>[x.id,x]));const groups=new Map();
  for(const [index,message]of messages.entries()){const contact=known.get(message.contactId);if(!contact||typeof message.text!=='string'||!message.text.trim())continue;const text=message.text.slice(0,4000),id='reply:'+floorId+':'+index+':'+messageHash(message.contactId+'\n'+text);const previous=this.get(contact.id).find(x=>sourceFloor(x,floorId)&&x.text===text);const entry={id,from:'npc',name:contact.name,text,time:previous?.time??Date.now(),status:'received',sourceFloorId:floorId};if(!groups.has(contact.id))groups.set(contact.id,[]);groups.get(contact.id).push(entry);}
  for(const id of new Set([...Object.keys(this.state.threads),...groups.keys()])){const thread=this.get(id),position=thread.findIndex(x=>sourceFloor(x,floorId)),clean=thread.filter(x=>!sourceFloor(x,floorId));clean.splice(position<0?clean.length:position,0,...groups.get(id)??[]);Object.defineProperty(this.state.threads,id,{value:clean,writable:true,enumerable:true,configurable:true});}
  this.state.schema=2;this.state.seen=this.state.seen.filter(id=>!id.startsWith('reply:'+floorId+':'));
  if(JSON.stringify(before)===JSON.stringify(this.state))return false;try{await this.save();}catch(error){this.state=before;throw error;}return true;
 });}
 async retainFloors(floorIds){return this.serial(async()=>{const allowed=new Set(floorIds.map(String)),before=clone(this.state);let changed=false;for(const [id,thread]of Object.entries(this.state.threads)){const next=thread.filter(message=>{const source=message.sourceFloorId??(/^reply:([^:]+):/.exec(message.id)?.[1]);return message.from!=='npc'||source===undefined||allowed.has(source);});if(next.length!==thread.length){this.state.threads[id]=next;changed=true;}}if(changed)try{await this.save();}catch(error){this.state=before;throw error;}return changed;});}
}
export function mountContactChat(container,{store,notify=()=>{},initialContact=''}){
 const doc=container.ownerDocument,motion=installSerialMotion(doc),root=doc.createElement('section');root.className='contact-chat';container.append(root);let lastThread='',lastCount=-1;let contactId=initialContact,draft='',busy=false,destroyed=false,notice='';const avatar=contact=>contact.head?`<img src="${esc(contact.head)}" alt="${esc(contact.name)}">`:`<span>${esc(contact.name.slice(0,1))}</span>`;
 const style=doc.createElement('style');style.textContent=`.contact-chat{height:100%;display:flex;flex-direction:column;background:#f4f0f6;color:#443b53;font:14px system-ui;overflow:hidden}.contact-chat header{display:flex;align-items:center;gap:12px;padding:15px 18px;border-bottom:1px solid #dcd3e3;background:#faf7fbee;flex:none}.contact-chat header h1{font-size:25px;margin:4px 0;font-weight:650}.contact-chat header button{border:0;background:none;color:#946aaa;font-size:20px;cursor:pointer}.contact-chat header strong{font-size:14px}.contact-chat header small{display:block;color:#9a8b9e;font-size:10px;margin-top:2px}.contact-chat main{flex:1;min-height:0;overflow:auto;padding:12px 15px;scrollbar-width:thin}.contact-avatar{width:48px;height:48px;flex:none;display:grid;place-items:center;background:linear-gradient(140deg,#f2d9e7,#d6dcef);border-radius:15px;color:#9b789f;overflow:hidden}.contact-avatar img{width:100%;height:100%;object-fit:contain}.contact-list-row{display:flex;gap:12px;align-items:center;width:100%;padding:13px 5px;text-align:left;border:0;border-bottom:1px solid #e1d8e5;background:none;color:#55445d;cursor:pointer}.contact-list-row>span:nth-child(2){flex:1;min-width:0}.contact-list-row strong{font-size:13px;font-weight:600}.contact-list-row p{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#9b8da2;margin:5px 0}.contact-message{display:flex;gap:8px;align-items:flex-end;margin:14px 0}.contact-message.user{flex-direction:row-reverse;margin-left:18%}.contact-message.npc{margin-right:18%}.contact-message .contact-avatar{width:30px;height:30px;border-radius:10px}.contact-bubble{max-width:100%;padding:11px 14px;border-radius:16px 16px 16px 4px;background:#fff;color:#62516b;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;box-shadow:0 3px 10px #71507a08}.contact-message.user .contact-bubble{background:linear-gradient(130deg,#a78abd,#8d779d);color:white;border-radius:16px 16px 4px 16px}.contact-message small{display:block;font-size:9px;color:#a89bad;text-align:right;margin-top:5px}.contact-chat form{display:flex;gap:8px;padding:12px 14px;background:#fcf9fd;border-top:1px solid #e2d9e7;align-items:flex-end;flex:none}.contact-chat textarea{flex:1;min-width:0;max-height:100px;min-height:39px;border:1px solid #d8cbdf;background:#f8f3fa;border-radius:15px;color:#65566e;padding:10px 12px;font:12px/1.6 system-ui;resize:none;box-sizing:border-box}.contact-chat form button{border:0;border-radius:50%;background:#977daa;color:#fff;width:35px;height:35px;font-size:17px;cursor:pointer}.contact-chat form button:disabled{opacity:.4}.contact-hint{font-size:9px;color:#b0a1b7;text-align:center;padding:3px 0 7px;background:#fcf9fd}.contact-services{padding:12px 16px;max-height:46%;overflow:auto;background:#eee7f2;flex:none}.contact-services>p{font-size:10px;color:#9d8aa7;margin:0 0 8px}.contact-services>button{display:grid;grid-template-columns:1fr auto;gap:5px;width:100%;border:0;border-radius:12px;padding:11px 13px;margin:6px 0;background:#fffbfe;color:#695371;text-align:left;cursor:pointer}.contact-services button>span{font-size:10px;grid-column:1;color:#9a88a1}.contact-services button>small{font-size:10px;grid-column:2;grid-row:1/3;color:#91759f;align-self:center}.contact-services button:disabled{opacity:.4;cursor:default}.contact-chat [data-contact-services]{font-size:12px;margin-left:auto}.contact-chat textarea:disabled{opacity:.5}@media(orientation:landscape){.contact-chat header{padding:9px 18px}.contact-chat header h1{font-size:21px}.contact-chat main{padding:5px 20px}.contact-chat form{padding:7px 18px}.contact-chat .contact-services{max-height:36%}}.phone16-root[data-orientation="landscape"] .contact-chat header{padding:9px 18px}.phone16-root[data-orientation="landscape"] .contact-chat main{padding:5px 20px}.phone16-root[data-orientation="landscape"] .contact-chat form{padding:7px 18px}.phone16-root[data-orientation="landscape"] .contact-services{max-height:36%}.contact-empty{color:#b0a1b7;text-align:center;margin:45px 0;font-size:12px}`;root.append(style);const content=doc.createElement('div');content.style.display='contents';root.append(content);
 function render(){if(destroyed)return;const contact=store.contacts.find(x=>x.id===contactId);if(!contact){patchHtml(content,`<header><div><h1>消息</h1><small>与你相连的人</small></div></header><main>${store.contacts.map(person=>`<button class="contact-list-row" id="contact-row-${esc(encodeURIComponent(person.id))}" data-contact="${esc(person.id)}"><span class="contact-avatar">${avatar(person)}</span><span><strong>${esc(person.name)}</strong><p>${esc(store.get(person.id).at(-1)?.text||person.subtitle||'还没有消息')}</p></span><span>›</span></button>`).join('')}</main>`);return;}
  patchHtml(content,`<header><button data-contact-back aria-label="返回联系人">‹</button><span class="contact-avatar">${avatar(contact)}</span><div><strong>${esc(contact.name)}</strong><small>${esc(contact.subtitle||'手机联系人')}</small></div></header><main>${store.get(contactId).map(message=>`<article class="contact-message ${message.from==='user'?'user':'npc'}" id="contact-message-${esc(encodeURIComponent(message.id))}" data-message-id="${esc(message.id)}">${message.from==='npc'?`<span class="contact-avatar">${avatar(contact)}</span>`:''}<div><div class="contact-bubble">${esc(message.text)}</div>${message.from==='user'?`<small>${message.status==='scheduled'?'待日程发送':'已送出'}</small>`:''}</div></article>`).join('')||'<p class="contact-empty">从一句问候开始吧。</p>'}</main><form><textarea data-chat-draft aria-label="消息内容" maxlength="2000" ${!store.isWritable()?'disabled':''} placeholder="写一条消息…">${esc(draft)}</textarea><button aria-label="发送角色消息" ${busy||!store.isWritable()?'disabled':''}>↑</button></form><div class="contact-hint">${esc(notice||(store.isWritable()?'消息会加入选中的日程格':'正在查看历史，消息仅供浏览'))}</div>`);const main=content.querySelector('main'),count=store.get(contactId).length;if(main&&(contactId!==lastThread||count!==lastCount))main.scrollTo(0,main.scrollHeight);lastThread=contactId;lastCount=count;
 }
 const tell=message=>{notice=String(message);notify(notice);};const unsubscribe=store.subscribe(render);root.addEventListener('input',e=>{if(e.target.hasAttribute('data-chat-draft'))draft=e.target.value;});root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.contact){contactId=b.dataset.contact;draft='';notice='';render();}if(b.hasAttribute('data-contact-back')){contactId='';draft='';notice='';render();}});root.addEventListener('submit',e=>{e.preventDefault();if(busy||!store.isWritable())return;void motion.run(async()=>{busy=true;render();try{const id=await store.send(contactId,draft);draft='';render();const bubble=root.querySelector(`[data-message-id="${id}"]`);if(bubble?.animate)await waitMotion(bubble.animate([{opacity:0,translate:'24px 20px',scale:.85},{opacity:1,translate:'0 0',scale:1}],{duration:320,easing:'cubic-bezier(.2,.8,.2,1)'}));}catch(error){tell(error.message);}finally{busy=false;render();}});});render();return{root,open(id){contactId=id;draft='';render();},destroy(){destroyed=true;unsubscribe();root.remove();}};
}
